/* ==============================================
   Volta Studio — Shared Styles
   ============================================== */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400;1,500&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --text-light: #8C8782;
  --accent: #C4735A;
  --accent-sage: #8B9E85;
  --accent-sand: #D4C5B9;
  --accent-ochre: #B8956A;
  --border: rgba(26, 26, 26, 0.08);
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-weight: 400;
  min-height: 100vh;
}

/* ==============================================
   Typography
   ============================================== */

h1, h2, h3, h4, .serif {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

p {
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.7;
}

a {
  color: inherit;
  text-decoration: none;
  transition: opacity 0.2s ease;
}

a:hover {
  opacity: 0.6;
}

/* ==============================================
   Header / Navigation
   ============================================== */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem 2.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg);
  mix-blend-mode: normal;
}

.site-header::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 2.5rem;
  right: 2.5rem;
  height: 1px;
  background: var(--border);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text);
  position: relative;
  z-index: 200;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2.25rem;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-sans);
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  transition: color 0.2s ease;
}

.nav-links a:hover {
  color: var(--text);
  opacity: 1;
}

.nav-links a.active {
  color: var(--text);
}

/* Hamburger */

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  background: none;
  border: none;
  cursor: pointer;
  position: relative;
  z-index: 200;
  padding: 0;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text);
  transition: transform 0.3s ease, opacity 0.3s ease;
  transform-origin: center;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
  transform: scaleX(0);
}

.hamburger.active span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}

/* Mobile overlay */

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.5rem;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: 2.25rem;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.01em;
  transition: opacity 0.2s ease;
}

.mobile-overlay a:hover {
  opacity: 0.5;
}

/* ==============================================
   Page padding (offsets fixed header)
   ============================================== */

.page-content {
  padding-top: 5.5rem;
}

/* ==============================================
   Hero (Home)
   ============================================== */

.hero {
  padding: 5rem 2.5rem 4rem;
  max-width: 1100px;
}

.hero h1 {
  font-size: clamp(2.5rem, 5.5vw, 5rem);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.02em;
  max-width: 14ch;
}

/* ==============================================
   Media Showcase (Home)
   ============================================== */

.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  padding: 0 2.5rem 4rem;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 2px;
}

.media-block.terracotta {
  background: #C4735A;
}

.media-block.sage {
  background: #8B9E85;
}

.media-block.sand {
  background: #C4A882;
}

/* ==============================================
   Client Marquee
   ============================================== */

.marquee-section {
  padding: 3rem 0 4rem;
  overflow: hidden;
}

.marquee-row {
  overflow: hidden;
  padding: 0.75rem 0;
  border-top: 1px solid var(--border);
}

.marquee-row:last-child {
  border-bottom: 1px solid var(--border);
}

.marquee-track {
  display: flex;
  width: max-content;
  animation-play-state: running;
}

.marquee-row:hover .marquee-track {
  animation-play-state: paused;
}

.marquee-track.left {
  animation: marquee-left 40s linear infinite;
}

.marquee-track.right {
  animation: marquee-right 40s linear infinite;
}

.marquee-track.left-slow {
  animation: marquee-left 55s linear infinite;
}

.marquee-content {
  display: flex;
  gap: 0;
  flex-shrink: 0;
}

.marquee-content span {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 600;
  white-space: nowrap;
  padding: 0 1.5rem;
  color: var(--text);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.marquee-content span.separator {
  color: var(--accent);
  font-weight: 400;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* ==============================================
   About Section (Home)
   ============================================== */

.about {
  padding: 5rem 2.5rem 6rem;
  max-width: 900px;
}

.about-label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.about h2 {
  font-family: var(--font-sans);
  font-size: clamp(1.15rem, 2vw, 1.35rem);
  font-weight: 500;
  line-height: 1.7;
  color: var(--text);
  max-width: 38rem;
  margin-bottom: 1.75rem;
}

.about h2 + h2 {
  margin-top: -0.5rem;
}

.about .philosophy-tag {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: 1rem;
  font-weight: 700;
  font-style: italic;
  color: var(--accent);
  margin-top: 0.5rem;
}

/* ==============================================
   Founder Letter (Neweno)
   ============================================== */

.letter-hero {
  padding: 4rem 2.5rem 2rem;
  max-width: 900px;
}

.letter-hero .label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.letter-hero h1 {
  font-size: clamp(2.25rem, 4.5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  max-width: 15ch;
}

.letter-hero .subtitle {
  font-family: var(--font-sans);
  font-size: 1.05rem;
  color: var(--text-muted);
  margin-top: 1rem;
  font-weight: 400;
}

.letter-body {
  padding: 2rem 2.5rem 6rem;
  max-width: 680px;
}

.letter-body p {
  font-family: var(--font-serif);
  font-size: clamp(1.1rem, 2vw, 1.3rem);
  line-height: 1.8;
  color: var(--text);
  margin-bottom: 1.5rem;
  font-weight: 400;
}

.letter-body .dropcap::first-letter {
  float: left;
  font-family: var(--font-serif);
  font-size: 4.5rem;
  font-weight: 700;
  line-height: 0.8;
  padding-right: 0.5rem;
  padding-top: 0.25rem;
  color: var(--accent);
}

.letter-body .signoff {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  font-style: italic;
  margin-top: 2.5rem;
  color: var(--text);
}

/* ==============================================
   Services
   ============================================== */

.services-intro {
  padding: 4rem 2.5rem 2rem;
  max-width: 900px;
}

.services-intro .label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.services-intro h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.02em;
  max-width: 15ch;
  margin-bottom: 1.5rem;
}

.services-intro .philosophy-text {
  font-family: var(--font-sans);
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--text);
  max-width: 36rem;
}

.services-divider {
  padding: 4rem 2.5rem;
}

.services-divider hr {
  border: none;
  height: 1px;
  background: var(--border);
}

.services-details {
  padding: 0 2.5rem 6rem;
  max-width: 1100px;
}

.services-details h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin-bottom: 3rem;
  max-width: 16ch;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2.5rem;
}

.service-card h3 {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  letter-spacing: -0.01em;
}

.service-card p {
  font-size: 0.95rem;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ==============================================
   Clients Page
   ============================================== */

.clients-intro {
  padding: 4rem 2.5rem 3rem;
  max-width: 900px;
}

.clients-intro h1 {
  font-size: clamp(2.25rem, 4.5vw, 4rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.clients-grid-section {
  padding: 0 2.5rem 6rem;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border-top: 1px solid var(--border);
}

.client-card {
  padding: 2rem 1.5rem;
  border-bottom: 1px solid var(--border);
  border-right: 1px solid var(--border);
  transition: background 0.2s ease;
}

.client-card:nth-child(3n) {
  border-right: none;
}

.client-card:hover {
  background: rgba(0,0,0,0.02);
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
  letter-spacing: -0.01em;
}

.client-card p {
  font-size: 0.85rem;
  line-height: 1.6;
  color: var(--text-muted);
}

.client-card.more {
  grid-column: 1 / -1;
  border-right: none;
  padding: 2rem 1.5rem;
}

.client-card.more h3 {
  font-size: 1.35rem;
}

/* ==============================================
   Contact Page
   ============================================== */

.contact-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: calc(100vh - 5.5rem);
  text-align: center;
  padding: 2rem;
}

.contact-section h1 {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 12vw, 14rem);
  font-weight: 800;
  line-height: 0.9;
  letter-spacing: -0.03em;
  color: var(--text);
  margin-bottom: 3rem;
}

.contact-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: -0.01em;
  transition: color 0.2s ease, opacity 0.2s ease;
}

.contact-links a:hover {
  color: var(--text);
  opacity: 1;
}

/* ==============================================
   Responsive
   ============================================== */

@media (max-width: 1024px) {
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .client-card:nth-child(3n) {
    border-right: 1px solid var(--border);
  }
  .client-card:nth-child(2n) {
    border-right: none;
  }
}

@media (max-width: 768px) {
  .site-header {
    padding: 1rem 1.25rem;
  }
  .site-header::after {
    left: 1.25rem;
    right: 1.25rem;
  }
  .nav-links {
    display: none;
  }
  .hamburger {
    display: flex;
  }
  .hero {
    padding: 3rem 1.25rem 2.5rem;
  }
  .media-showcase {
    grid-template-columns: 1fr;
    gap: 0.75rem;
    padding: 0 1.25rem 2.5rem;
  }
  .media-block {
    aspect-ratio: 16 / 9;
  }
  .media-block:nth-child(2) {
    aspect-ratio: 4 / 5;
  }
  .media-block:nth-child(3) {
    aspect-ratio: 3 / 4;
  }
  .about {
    padding: 3rem 1.25rem 4rem;
  }
  .letter-hero {
    padding: 3rem 1.25rem 1.5rem;
  }
  .letter-body {
    padding: 1.5rem 1.25rem 4rem;
  }
  .letter-body p {
    font-size: 1.05rem;
  }
  .services-intro {
    padding: 3rem 1.25rem 1.5rem;
  }
  .services-divider {
    padding: 2.5rem 1.25rem;
  }
  .services-details {
    padding: 0 1.25rem 4rem;
  }
  .services-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .clients-intro {
    padding: 3rem 1.25rem 2rem;
  }
  .clients-grid-section {
    padding: 0 1.25rem 4rem;
  }
  .clients-grid {
    grid-template-columns: 1fr;
  }
  .client-card {
    border-right: none;
  }
  .client-card:nth-child(3n) {
    border-right: none;
  }
  .client-card:nth-child(2n) {
    border-right: none;
  }
  .contact-section h1 {
    font-size: clamp(3rem, 16vw, 8rem);
  }
  .marquee-content span {
    font-size: clamp(1.2rem, 2.5vw, 2rem);
    padding: 0 1rem;
  }
}

